    "@thyrox/mcp-runtime": "0.1.0",
    "@thyrox/memory": "0.1.0",
    "@thyrox/output": "0.1.0",
    "@thyrox/permission": "0.1.0",
    "@thyrox/provider": "0.1.0",
    "@thyrox/repl": "0.0.0",
    "@thyrox/server": "0.1.0",
    "@thyrox/shell": "0.1.0",
    "@thyrox/stdin-napi": "1.0.0",
    "@thyrox/storage": "0.1.0",
    "@thyrox/swarm": "0.1.0",
    "@thyrox/teleport": "0.1.0",
    "@thyrox/tool-registry": "0.1.0",
    "@thyrox/voice": "0.0.0",
    "chalk": "^6.0.0",
    "lodash-es": "^4.18.1",
    "react": "^19.0.0",
    "signal-exit": "^4.1.0"
  },
